class ComponentError(RuntimeError):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def _sha(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def _json(path, value):
    path = Path(path)
    temporary = path.with_name(path.name + '.' + uuid.uuid4().hex + '.tmp')
    try:
        with temporary.open('w') as stream:
            json.dump(value, stream, allow_nan=False, sort_keys=True)
            stream.flush()
            os.fsync(stream.fileno())
        temporary.replace(path)
    finally:
        temporary.unlink(missing_ok=True)


@dataclasses.dataclass(frozen=True)
class Config:
    """Deployment configuration; never accept these paths from upload metadata."""
    weights_dir: str
    cavity_weights_dir: str
    wall_weights_dir: str
    joint_source_model: str
    python: str = sys.executable
    device: str = 'cpu'
    threads: int = 1
    timeout_seconds: float = 3600.
    idle_seconds: float = 300.
    decode_bytes: int = 536870912
    address_mb: int = 32768
    allow_estimated_anatomy: bool = False

    @classmethod
    def from_environment(cls):
        models = Path(os.environ.get('CHRONO_MODEL_ROOT', Path(__file__).resolve().parent.parent / 'models'))
        return cls(
            weights_dir=os.environ.get('CHRONO_WEIGHTS_DIR', str(models / 'chrono_union')),
            cavity_weights_dir=os.environ.get('CHRONO_CAVITY_WEIGHTS_DIR', str(models / 'lv_cavity')),
            wall_weights_dir=os.environ.get('CHRONO_WALL_WEIGHTS_DIR', str(models / 'myocardial_wall')),
            joint_source_model=os.environ.get('CHRONO_JOINT_SOURCE_MODEL', str(models / 'joint_source/model.onnx')),
            python=os.environ.get('CHRONO_PYTHON', sys.executable),
            device=os.environ.get('CHRONO_DEVICE', 'cpu'),
            threads=int(os.environ.get('CHRONO_NUM_THREADS', '1')),
            timeout_seconds=float(os.environ.get('CHRONO_TIMEOUT_SECONDS', '3600')),
            idle_seconds=float(os.environ.get('CHRONO_IDLE_SECONDS', '300')),
            decode_bytes=int(os.environ.get('CHRONO_MAX_DECODE_BYTES', '536870912')),
            address_mb=int(os.environ.get('CHRONO_WORKER_ADDRESS_MB', '32768')),
            allow_estimated_anatomy=os.environ.get('CHRONO_ALLOW_ESTIMATED_ANATOMY', '').lower() in ('1', 'true', 'yes'))

    def validate(self):
        if self.device != 'cpu' and not self.device.startswith('cuda'):
            raise ComponentError('configuration_error', 'Choose cpu or an explicitly allocated CUDA device.')
        if any(type(x) is not int or x < 1 for x in (self.threads, self.decode_bytes, self.address_mb)):
            raise ComponentError('configuration_error', 'Resource budgets must be positive integers.')
        if any(not math.isfinite(x) or x <= 0 for x in (self.timeout_seconds, self.idle_seconds)):
            raise ComponentError('configuration_error', 'Processing deadlines must be positive and finite.')
        if not Path(self.python).is_file():
            raise ComponentError('configuration_error', 'The tracking Python environment is unavailable.')
        for name in ('weights_dir', 'cavity_weights_dir', 'wall_weights_dir', 'joint_source_model', 'python'):
            if not Path(getattr(self, name)).is_absolute():
                raise ComponentError('configuration_error', 'Model and interpreter paths must be absolute.')

    def environment(self):
        env = dict(os.environ)
        for name in ('PYTHONPATH', 'PYTHONHOME'):
            env.pop(name, None)
        env['PYTHONNOUSERSITE'] = '1'
        env['PATH'] = str(Path(self.python).parent) + os.pathsep + env.get('PATH', os.defpath)
        env.update(CHRONO_WEIGHTS_DIR=self.weights_dir, CHRONO_CAVITY_WEIGHTS_DIR=self.cavity_weights_dir,
            CHRONO_WALL_WEIGHTS_DIR=self.wall_weights_dir, CHRONO_JOINT_SOURCE_MODEL=self.joint_source_model,
            CHRONO_OBSERVED_SOURCE_RECOVERY='joint_common_v28', MTCHRONO_SDPA='0',
            CHRONO_ALLOW_ESTIMATED_ANATOMY=str(self.allow_estimated_anatomy).lower(),
            CHRONO_CONDITIONAL_ESTIMATOR='coherent57',
            CHRONO_CONDITIONAL_ESTIMATOR_SHA256='26667d901a9b544d094229ca4af945ce1a25cd7e0ed94c0ddc61b9c79feb7794',
            OMP_NUM_THREADS=str(self.threads), OPENBLAS_NUM_THREADS=str(self.threads),
            MKL_NUM_THREADS=str(self.threads), STUDIO_MAX_DECODE_BYTES=str(self.decode_bytes),
            PYTHONDONTWRITEBYTECODE='1')
        if self.device == 'cpu':
            env['CUDA_VISIBLE_DEVICES'] = ''
        return env


