RUNTIME_PROBE = 'import importlib.util, pathlib, sys\nimport cv2, einops, numpy, onnxruntime, osqp, pydicom, scipy, segmentation_models_pytorch, torch, torchvision\nassert torch.version.cuda is None, torch.version.cuda\nassert "CPUExecutionProvider" in onnxruntime.get_available_providers()\nassert "FFMPEG:                      YES" in cv2.getBuildInformation()\nassert not any("Pipeline/.venv" in p or "EchoForge_Studio/.venv-integration" in p for p in sys.path)\nspec = importlib.util.spec_from_file_location("isolated_tracker_probe", sys.argv[1])\nmodule = importlib.util.module_from_spec(spec)\nsys.modules[spec.name] = module\nspec.loader.exec_module(module)\nengine = module._engine()\nmodule._io()\nfor version in ("15", "19", "27"):\n    engine._material_solver(version)\nprint("CPU runtime and all embedded solver imports passed")\n\nimport imageio_ffmpeg, subprocess\nencoder = pathlib.Path(imageio_ffmpeg.get_ffmpeg_exe())\nsubprocess.run([str(encoder), \'-version\'], check=True, stdout=subprocess.DEVNULL)\nlink = pathlib.Path(sys.executable).parent / \'ffmpeg\'\nlink.unlink(missing_ok=True)\nlink.symlink_to(encoder)\nprint(\'Private video encoder passed\')\n'


def _assets(config):
    rows = []
    for group, filenames in ASSET_PINS.items():
        root = Path(getattr(config, group))
        for filename, expected in filenames:
            path = root / filename if filename else root
            if not path.is_file():
                raise ComponentError('models_unavailable', 'The configured tracking model assets are incomplete.')
            if _sha(path) != expected:
                raise ComponentError('model_integrity_error', 'A model differs from the trusted released weight.')
            rows.append(dict(path=str(path), sha256=expected, bytes=path.stat().st_size))
    return rows


def _engine():
    name = '_echo_chrono_shared_v63_isolated'
    if name not in sys.modules:
        if hashlib.sha256(ENGINE_SOURCE.encode()).hexdigest() != ENGINE_SHA256:
            raise ComponentError('source_integrity_error', 'Embedded scientific source was modified.')
        module = types.ModuleType(name)
        module.__file__ = __file__
        sys.modules[name] = module
        try:
            exec(compile(ENGINE_SOURCE, '<chrono-frozen-v57>', 'exec'), module.__dict__)
            _install_worker_execution_cache(module)
            _install_shared_recovery(module)
        except BaseException:
            sys.modules.pop(name, None)
            raise
    return sys.modules[name]


def _io():
    name = '_echo_chrono_native_io_v63_isolated'
    if name not in sys.modules:
        module = types.ModuleType(name)
        module.__dict__['_engine'] = _engine
        sys.modules[name] = module
        try:
            exec(compile(IO_SOURCE, '<chrono-native-io-v58>', 'exec'), module.__dict__)
        except BaseException:
            sys.modules.pop(name, None)
            raise
    return sys.modules[name]


def _manifest(folder):
    rows = []
    for path in sorted(Path(folder).rglob('*')):
        if path.is_symlink():
            raise ComponentError('invalid_artifact', 'Linked artifacts are not accepted.')
        if path.is_file() and path.name != 'receipt.json':
            rows.append(dict(name=str(path.relative_to(folder)), bytes=path.stat().st_size, sha256=_sha(path)))
    return rows


def _accepted(folder, key):
    try:
        receipt = json.loads((folder / 'receipt.json').read_text())
        return (receipt['status'] == 'complete' and receipt['cache_key'] == key
                and receipt['component_sha256'] == _sha(__file__)
                and receipt['artifacts'] == _manifest(folder))
    except (OSError, ValueError, KeyError, TypeError, ComponentError):
        return False


def _descriptor(folder, key, public_base_url):
    descriptor = json.loads((folder / 'descriptor.json').read_text())
    # Only job-relative routes are accepted; no upload text is interpolated into HTML.
    base = public_base_url.rstrip('/')
    if base and (not base.startswith('/') or base.startswith('//') or any(c in base for c in ('?', '#', '\\', '\n', '\r'))):
        raise ComponentError('configuration_error', 'Use a local job artifact URL prefix.')
    descriptor.update(schema_version=API_VERSION, component_version=COMPONENT_VERSION,
        cache_key=key, viewer_url=f'{base}/chrono/{key}/viewer.html' if base else f'chrono/{key}/viewer.html',
        data_url=f'{base}/chrono/{key}/tracking.json' if base else f'chrono/{key}/tracking.json',
        arrays_url=f'{base}/chrono/{key}/tracking.npz' if base else f'chrono/{key}/tracking.npz')
    preview = descriptor.get('preview')
    if isinstance(preview, dict) and preview.get('status') == 'complete':
        filename = preview.get('file')
        if filename not in ('preview.mp4', 'preview.webm'):
            raise ComponentError('invalid_artifact', 'Unexpected tracking preview path.')
        preview['url'] = f'{base}/chrono/{key}/{filename}' if base else f'chrono/{key}/{filename}'
    return descriptor


def run_tracking(input_path, *, output_dir, public_base_url='', config=None, progress=None, cancelled=None):
    """Process one immutable upload. Reuses only authenticated complete results.

    All scientific work stays in a child; imports, Torch thread settings and
    GPU visibility never change the host process. One retry handles a native
    crash; a deterministic failure is returned immediately. The host owns its
    queue/restart lifecycle and may call again with the retained input.
    """
    import fcntl
    import shutil
    source = Path(input_path).resolve(strict=True)
    if not source.is_file() or source.stat().st_size == 0:
        raise ComponentError('invalid_input', 'A nonempty uploaded cine is required.')
    if source.suffix.lower() not in ('.dcm', '.mp4', '.avi', '.mov', '.mkv'):
        raise ComponentError('invalid_input', 'Unsupported cine format.')
    config = config or _automatic_config(progress, cancelled)
    config.validate()
    root = Path(output_dir).resolve() / 'chrono'
    if root.is_symlink():
        raise ComponentError('invalid_artifact', 'A linked component output directory was rejected.')
    root.mkdir(parents=True, exist_ok=True)
    identity = dict(version=COMPONENT_VERSION, component_sha256=_sha(__file__),
        input_sha256=_sha(source), input_bytes=source.stat().st_size,
        config=dataclasses.asdict(config), assets=_assets(config))
    key = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()
    destination = root / key
    if destination.is_symlink():
        raise ComponentError('invalid_artifact', 'A linked cached result was rejected.')
    with (root / ('.' + key + '.lock')).open('a') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            raise ComponentError('busy', 'This cine is already being tracked.') from error
        if destination.exists():
            if _accepted(destination, key):
                return _descriptor(destination, key, public_base_url)
            raise ComponentError('invalid_cached_result', 'A previous result failed integrity verification; it was retained for inspection.')
        staging = root / ('.' + key + '-' + uuid.uuid4().hex)
        staging.mkdir()
        try:
            with tempfile.TemporaryDirectory(prefix='echo-chrono-') as workspace:
                work = Path(workspace)
                for attempt in (1, 2):
                    if cancelled and cancelled():
                        raise ComponentError('cancelled', 'Tracking cancelled.')
                    request = dict(identity, cache_key=key, input_path=str(source), output_dir=str(staging),
                        parent_pid=os.getpid(), parent_birth=birth(os.getpid()), attempt=attempt,
                        progress_path=str(work / f'progress-{attempt}.json'),
                        receipt_path=str(work / f'receipt-{attempt}.json'))
                    request_path = work / f'request-{attempt}.json'
                    _json(request_path, request)
                    with (work / f'worker-{attempt}.log').open('wb') as log:
                        process = subprocess.Popen([config.python, '-B', str(Path(__file__).resolve()), '--worker', str(request_path)],
                            env=config.environment(), stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
                        record = dict(pid=process.pid, birth=birth(process.pid))
                        started = changed = time.monotonic()
                        previous = None
                        try:
                            while not exited_without_reaping(process):
                                if cancelled and cancelled():
                                    raise ComponentError('cancelled', 'Tracking cancelled.')
                                now = time.monotonic()
                                if now - started > config.timeout_seconds or now - changed > config.idle_seconds:
                                    raise ComponentError('processing_timeout', 'Tracking exceeded its processing budget.')
                                try:
                                    update = json.loads(Path(request['progress_path']).read_text())
                                except (OSError, ValueError):
                                    update = None
                                if update is not None and update != previous:
                                    previous, changed = update, now
                                    if progress:
                                        progress(update['fraction'], update['message'])
                                time.sleep(.1)
                        finally:
                            try:
                                stop_worker(record)
                            finally:
                                process.wait(timeout=5)
                    receipt_path = Path(request['receipt_path'])
                    if not receipt_path.is_file():
                        if attempt == 1:
                            # Incomplete files are never reused by a second inference attempt.
                            shutil.rmtree(staging)
                            staging.mkdir()
                            continue
                        raise ComponentError('worker_crashed', 'Tracking worker failed twice; the EF result is retained.')
                    receipt = json.loads(receipt_path.read_text())
                    if receipt.get('request_sha256') != _sha(request_path):
                        raise ComponentError('invalid_worker_receipt', 'Tracking receipt does not match its request.')
                    if receipt.get('status') != 'complete':
                        raise ComponentError(receipt.get('code', 'processing_failed'), receipt.get('message', 'Tracking could not complete.'))
                    if process.returncode != 0 or receipt['artifacts'] != _manifest(staging):
                        raise ComponentError('invalid_worker_receipt', 'Tracking artifacts could not be authenticated.')
                    if _sha(source) != identity['input_sha256'] or _sha(__file__) != identity['component_sha256']:
                        raise ComponentError('source_integrity_error', 'Source or upload changed during tracking.')
                    _json(staging / 'receipt.json', receipt)
                    staging.rename(destination)
                    return _descriptor(destination, key, public_base_url)
        finally:
            if staging.exists():
                shutil.rmtree(staging)


def attach_tracking(input_path, *, output_dir, public_base_url='', config=None, progress=None, cancelled=None):
    """Fail-contained host adapter: an optional tracking error never erases EF."""
    try:
        return run_tracking(input_path, output_dir=output_dir, public_base_url=public_base_url,
            config=config, progress=progress, cancelled=cancelled)
    except Exception as error:
        logging.getLogger(__name__).exception('Optional tracking did not complete; host result retained')
        code = getattr(error, 'code', 'processing_failed')
        return dict(schema_version=API_VERSION, component_version=COMPONENT_VERSION,
            status='unavailable' if code in ('models_unavailable', 'runtime_unavailable', 'configuration_error') else 'failed',
            code=code, message=str(error) if isinstance(error, ComponentError) else 'Tracking could not complete for this cine.')


def _write_viewer(folder, payload, frames, fps):
    """Exact native PNGs; imagery and trajectories always advance as one frame."""
    import cv2
    folder = Path(folder)
    image_dir = folder / 'frames'
    image_dir.mkdir(exist_ok=True)
    for index, frame in enumerate(frames):
        if not cv2.imwrite(str(image_dir / f'{index:06d}.png'), frame, [cv2.IMWRITE_PNG_COMPRESSION, 1]):
            raise ComponentError('artifact_write_failed', 'An acquired display frame could not be saved.')
    _json(folder / 'display.json', dict(num_frames=len(frames), width=int(frames[0].shape[1]),
        height=int(frames[0].shape[0]), fps=float(fps or 30.), estimated_fps=not bool(fps),
        source_pixels='lossless_native_grayscale', native_order=True))
    (folder / 'viewer.html').write_text(VIEWER_HTML)


# Execution-only reuse. Original model calls, candidate selection and gates stay frozen.
def _install_worker_execution_cache(engine):
    import collections
    import copy
    import threading
    import numpy as np
    original_hash = engine._file_sha256
    verified = {}
    lock = threading.RLock()
    def file_identity(path):
        stat = Path(path).stat()
        return (stat.st_dev, stat.st_ino, stat.st_size, stat.st_mtime_ns, stat.st_ctime_ns)
    def verified_hash(path):
        path = Path(path).resolve()
        before = file_identity(path)
        # Fresh writes may share a coarse filesystem timestamp. Cache only
        # stable assets, and still authenticate all assets at publication.
        stable = time.time_ns() - max(before[-2:]) > 1_000_000_000
        with lock:
            if stable and verified.get(path, (None,))[0] == before:
                return verified[path][1]
            digest = original_hash(path)
            if file_identity(path) != before:
                raise ComponentError('model_integrity_error', 'A tracking asset changed during authentication.')
            if stable:
                verified[path] = (before, digest)
            else:
                verified.pop(path, None)
            return digest
    engine._file_sha256 = verified_hash
    cache = collections.OrderedDict()
    usage = 0
    budget = 512 * 1024**2
    stats = {'segmentation_cache_hits': 0, 'segmentation_cache_misses': 0,
             'maximum_cached_array_bytes': 0}
    def size(value):
        if isinstance(value, np.ndarray): return value.nbytes
        if isinstance(value, (tuple, list)): return sum(size(v) for v in value)
        if isinstance(value, dict): return sum(size(v) for v in value.values())
        return 0
    def wrap(name):
        operation = getattr(engine, name)
        def call(frame, *args, **kwargs):
            nonlocal usage
            image = np.ascontiguousarray(frame)
            # Model directory, colour order and device remain part of the key.
            key = (name, image.shape, image.dtype.str,
                   hashlib.sha256(memoryview(image)).hexdigest(),
                   repr(args), repr(sorted(kwargs.items())))
            with lock:
                if key in cache:
                    value, count = cache.pop(key); cache[key] = (value, count)
                    stats['segmentation_cache_hits'] += 1
                    return copy.deepcopy(value)
            value = operation(frame, *args, **kwargs)
            stats['segmentation_cache_misses'] += 1
            count = size(value)
            if count <= budget:
                with lock:
                    while cache and usage + count > budget:
                        _, (_, removed) = cache.popitem(last=False); usage -= removed
                    cache[key] = (copy.deepcopy(value), count); usage += count
                    stats['maximum_cached_array_bytes'] = max(stats['maximum_cached_array_bytes'], usage)
            return value
        setattr(engine, name, call)
    for name in ('_conditional_fields_v55', 'predict_cavity_mask', 'predict_wall_probability'):
        wrap(name)
    engine.EXECUTION_CACHE_STATS = stats


def _reuse_completed_upload(request, config, receipt):
    """Reuse only a complete, authenticated identical upload still held by Studio.

    This creates no extra persistent cache or retention beyond existing job
    outputs. Deleting the earlier job also removes its reuse source. The sole
    compatible historical component has identical embedded scientific sources.
    """
    import shutil
    staging = Path(request['output_dir']).resolve()
    if staging.parent.name != 'chrono' or staging.parent.parent.name != 'output':
        return False
    jobs = staging.parents[3]
    identities = [request['component_sha256'],
                  'a497c67d3eb5a6f370d6f3466ae7fdcb03bef4cfc7e2f7bd1496cacdb95d92c0']
    base = {name: request[name] for name in
            ('version', 'component_sha256', 'input_sha256', 'input_bytes', 'config', 'assets')}
    for component_hash in dict.fromkeys(identities):
        identity = dict(base, component_sha256=component_hash)
        key = hashlib.sha256(json.dumps(identity, sort_keys=True).encode()).hexdigest()
        for folder in sorted(jobs.glob('*/output/chrono/' + key)):
            if folder.is_symlink() or folder.resolve() == staging:
                continue
            if jobs not in folder.resolve().parents:
                continue
            try:
                old = json.loads((folder / 'receipt.json').read_text())
                if (old.get('status') != 'complete' or old.get('cache_key') != key
                        or old.get('component_sha256') != component_hash
                        or old.get('input_sha256') != request['input_sha256']
                        or old.get('engine_sha256') != ENGINE_SHA256
                        or old.get('shared_recovery_version') != 62
                        or old.get('recovery_kernel_revision') != 9
                        or old.get('scientific_source_sha256') !=
                            {name: digest for name, (_, digest) in REPAIR_SOURCES.items()}
                        or old.get('artifacts') != _manifest(folder)):
                    continue
                if _assets(config) != request['assets']:
                    raise ComponentError('model_integrity_error', 'Tracking model assets changed.')
                for item in folder.iterdir():
                    if item.name == 'receipt.json':
                        continue
                    if item.is_dir(): shutil.copytree(item, staging / item.name)
                    else: shutil.copy2(item, staging / item.name)
                if _manifest(staging) != old['artifacts']:
                    raise ComponentError('invalid_cached_result', 'Prior tracking outputs changed while copied.')
                receipt.update(status='complete', artifacts=_manifest(staging),
                    acquired_frames=old['acquired_frames'], input_sha256=request['input_sha256'],
                    engine_sha256=ENGINE_SHA256, shared_recovery_version=62, recovery_kernel_revision=9,
                    scientific_source_sha256=old['scientific_source_sha256'], attempt=request['attempt'],
                    worker=dict(pid=os.getpid(), birth=birth(os.getpid()),
                                python_version=sys.version, interpreter=sys.executable),
                    execution_reuse=dict(source=str(folder), receipt_sha256=_sha(folder/'receipt.json'),
                                         identical_upload_and_models=True, scientific_sources_identical=True))
                return True
            except (OSError, ValueError, KeyError, TypeError, ComponentError):
                # An unrelated corrupt prior result cannot block a fresh inference.
                for item in staging.iterdir():
                    if item.is_dir(): shutil.rmtree(item)
                    else: item.unlink()
    return False


def _worker(request_path):
    import ctypes
    import resource
    request_path = Path(request_path)
    request = json.loads(request_path.read_text())
    receipt = dict(request_sha256=_sha(request_path), cache_key=request['cache_key'],
        component_sha256=request['component_sha256'], status='failed')
    ctypes.CDLL(None, use_errno=True).prctl(1, signal.SIGKILL)
    if os.getppid() != request['parent_pid'] or birth(os.getppid()) != request['parent_birth']:
        raise SystemExit('Parent identity changed before admission.')
    config = Config(**request['config'])
    resource.setrlimit(resource.RLIMIT_AS, (config.address_mb * 1024**2,) * 2)
    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    def progress(fraction, message):
        _json(request['progress_path'], dict(fraction=float(fraction), message=str(message), tick=time.monotonic()))
    try:
        if _sha(__file__) != request['component_sha256'] or _sha(request['input_path']) != request['input_sha256']:
            raise ComponentError('source_integrity_error', 'Component or upload identity changed.')
        if _reuse_completed_upload(request, config, receipt):
            progress(1., 'Loaded verified tracking and strain for this video')
            _json(request['receipt_path'], receipt)
            return
        progress(0, 'Loading tracking runtime')
        io = _io()
        engine = _engine()
        if io._engine() is not engine or getattr(engine, 'SHARED_RECOVERY_VERSION', None) != 62:
            raise ComponentError('source_integrity_error', 'Portable worker is not bound to the qualified recovery engine.')
        io.cv2.setNumThreads(config.threads)
        frames, _ = io.read_input(request['input_path'])
        progress(.02, 'Locating myocardial anatomy')
        options = dict(weights_dir=config.weights_dir, cavity_weights_dir=config.cavity_weights_dir,
            wall_weights_dir=config.wall_weights_dir, device=config.device, num_threads=config.threads,
            progress=progress, cancelled=lambda: os.getppid() != request['parent_pid'],
            repair_motion=True, write_preview=True)
        result = {}
        io._append_tracking(result, frames, request['input_path'], request['output_dir'], options)
        descriptor = result['tracking']
        descriptor['preview'] = result.get('preview')
        if descriptor['status'] != 'complete':
            raise ComponentError(descriptor.get('code', 'tracking_failed'), descriptor.get('message', 'Tracking failed.'))
        folder = Path(request['output_dir'])
        payload = json.loads((folder / 'tracking.json').read_text())
        progress(.96, 'Saving synchronized tracking and strain viewer')
        _, fps, timing_source = io._tracking_clock(request['input_path'], len(frames), {})
        descriptor.update(native_size=payload['native_size'],
            frame_indices=payload['frame_indices'], timestamps_ms=payload.get('timestamps_ms'),
            fps=float(fps) if fps else None, timing_source=timing_source)
        _write_viewer(folder, payload, frames, fps)
        _json(folder / 'descriptor.json', descriptor)
        if _assets(config) != request['assets']:
            raise ComponentError('model_integrity_error', 'Tracking model assets changed during inference.')
        receipt.update(execution_cache=dict(engine.EXECUTION_CACHE_STATS),
            status='complete', artifacts=_manifest(folder), acquired_frames=len(frames),
            input_sha256=request['input_sha256'], engine_sha256=ENGINE_SHA256,
            attempt=request['attempt'], worker=dict(pid=os.getpid(), birth=birth(os.getpid()),
                python_version=sys.version, interpreter=sys.executable),
            shared_recovery_version=62, recovery_kernel_revision=9,
            scientific_source_sha256={name: digest for name, (_, digest) in REPAIR_SOURCES.items()})
    except Exception as error:
        logging.exception('Isolated tracking error')
        receipt.update(code=getattr(error, 'code', 'runtime_unavailable' if isinstance(error, ImportError) else 'processing_failed'),
            message=str(error) if isinstance(error, ComponentError) else 'Tracking could not complete for this cine.')
    _json(request['receipt_path'], receipt)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('cine', nargs='?', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--worker', type=Path, help=argparse.SUPPRESS)
    parser.add_argument('--check', action='store_true', help='Check configured weight integrity without loading a model')
    args = parser.parse_args(argv)
    if args.worker:
        _worker(args.worker)
        return 0
    if args.check:
        config = Config.from_environment()
        config.validate()
        print(json.dumps(dict(status='configured', assets=len(_assets(config)), engine_sha256=ENGINE_SHA256)))
        return 0
    if not args.cine or not args.output:
        parser.error('Supply a cine and --output, or --check.')
    result = attach_tracking(args.cine, output_dir=args.output)
    print(json.dumps(result))
    return 0 if result['status'] == 'complete' else 1

# The reproducible packager appends frozen engine, native I/O, worker identity
# helpers and the embedded browser view below. No Pipeline imports are required.


def birth(pid):
    try:
        return int(Path(f'/proc/{pid}/stat').read_text().rsplit(')', 1)[1].split()[19])
    except (OSError, ValueError, IndexError):
        return None

def group_has_live_members(leader):
    """The unreaped leader reserves this process-group/session identity."""
    with os.scandir('/proc') as entries:
        for entry in entries:
            if not entry.name.isdecimal():
                continue
            try:
                fields = Path(entry.path, 'stat').read_text().rsplit(')', 1)[1].split()
                if int(fields[2]) == leader and int(fields[3]) == leader and fields[0] != 'Z':
                    return True
            except (OSError, ValueError, IndexError):
                continue
    return False

def stop_worker(record):
    """Signal only a still-authenticated process group created by this job."""
    pid = record.get('pid')
    identity = record.get('birth')
    if (type(pid) is not int or pid <= 0 or type(identity) is not int or identity <= 0
            or birth(pid) != identity):
        return False
    try:
        if os.getpgid(pid) != pid:
            raise ComponentError('worker_identity_error', 'Worker no longer owns its isolated process group.')
        os.killpg(pid, signal.SIGTERM)
    except ProcessLookupError:
        return True
    deadline = time.monotonic() + 2
    while time.monotonic() < deadline and birth(pid) == record['birth']:
        try:
            state = Path(f'/proc/{pid}/stat').read_text().rsplit(')', 1)[1].split()[0]
        except (OSError, IndexError):
            break
        if state == 'Z':
            # The child is deliberately not reaped yet: its PID/session is
            # reserved while any surviving native descendants are killed.
            break
        time.sleep(.05)
    # The original child is not reaped until its supervising Popen.wait below,
    # so its PID/PGID cannot be recycled before this group cleanup.
    if birth(pid) == record['birth']:
        try:
            os.killpg(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        # SIGKILL delivery is asynchronous. Wait for actual descendant death,
        # including a child that ignored SIGTERM, before retry/publication.
        deadline = time.monotonic() + 2
        while group_has_live_members(pid):
            if time.monotonic() >= deadline:
                raise ComponentError('worker_termination_failed', 'An isolated native descendant did not terminate; output was not accepted.')
            time.sleep(.02)
    return True

def exited_without_reaping(process):
    """Observe exit while retaining original PID/PGID ownership for cleanup."""
    try:
        return os.waitid(os.P_PID, process.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT) is not None
    except ChildProcessError:
        return True


def _repair_module(name):
    source, expected = REPAIR_SOURCES[name]
    if hashlib.sha256(source.encode()).hexdigest() != expected:
        raise ComponentError('source_integrity_error', 'Embedded recovery source was modified.')
    key = '_echo_chrono_v63_isolated_' + name + '_' + expected[:16]
    if key not in sys.modules:
        module = types.ModuleType(key)
        module.__file__ = __file__
        # Resolve only the pinned source-helper imports within this
        # component. Never modify sys.path or replace a host's global module.
        import builtins
        native_import = builtins.__import__
        aliases = {'source_shape_candidate_v62': 'source_shape',
                   'original_ensemble_conditional_v62': 'original_source',
                   'admitted_source_rerank_v9': 'admitted_source'}
        def isolated_import(module_name, globals=None, locals=None, fromlist=(), level=0):
            if level == 0 and module_name in aliases:
                return _repair_module(aliases[module_name])
            return native_import(module_name, globals, locals, fromlist, level)
        module.__dict__['__builtins__'] = dict(vars(builtins), __import__=isolated_import)
        sys.modules[key] = module
        try:
            exec(compile(source, '<chrono-shared-v62-' + name + '>', 'exec'), module.__dict__)
        except BaseException:
            sys.modules.pop(key, None)
            raise
    return sys.modules[key]


def _install_shared_recovery(module):
    return _repair_module('adapter').install(module, _repair_module('recovery'),
        _repair_module('support'), _repair_module('original_source'),
        _repair_module('observed_source'))


def __getattr__(name):
    # Retain the old in-process engine API for existing local EF hosts while
    # the preferred attach_tracking adapter keeps inference in its child.
    if name.startswith('__'):
        raise AttributeError(name)
    try:
        return getattr(_engine(), name)
    except AttributeError:
        raise AttributeError(name) from None


